function bruit238(k,vol,boucle,dur){const c=sndPret();const b=ECH236.buf[k];if(!c||!b)return null;const s=c.createBufferSource(),g=c.createGain();s.buffer=b;s.loop=!!boucle;const t=c.currentTime;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+(boucle?1.5:.03));
 if(dur){g.gain.setValueAtTime(vol,t+Math.max(.1,dur-1.2));g.gain.linearRampToValueAtTime(0,t+dur);s.stop(t+dur+.05)}s.connect(g);g.connect(SND.out);s.start();return {s,g,stop(f){try{g.gain.cancelScheduledValues(c.currentTime);g.gain.setValueAtTime(g.gain.value,c.currentTime);g.gain.linearRampToValueAtTime(0,c.currentTime+(f||1));s.stop(c.currentTime+(f||1)+.05)}catch(e){}}}}
